function escapeForQuote(value, quote) {
  let escaped = '';

  for (const char of value) {
    if (char === '\\') {
      escaped += '\\\\';
      continue;
    }

    if (char === quote) {
      escaped += `\\${quote}`;
      continue;
    }

    if (char === '\n') {
      escaped += '\\n';
      continue;
    }

    if (char === '\r') {
      escaped += '\\r';
      continue;
    }

    if (char === '\t') {
      escaped += '\\t';
      continue;
    }

    const code = char.charCodeAt(0);
    if (code < 32 || code === 127) {
      escaped += `\\x${code.toString(16).padStart(2, '0')}`;
      continue;
    }

    escaped += char;
  }

  return escaped;
}

export function pyStringRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  return `${quote}${escapeForQuote(value, quote)}${quote}`;
}

export function pyRepr(value) {
  if (typeof value === 'string') {
    return pyStringRepr(value);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : pyStringRepr(String(value));
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pyRepr(item)).join(', ')}]`;
  }

  const entries = Object.keys(value).map((key) => `${pyRepr(key)}: ${pyRepr(value[key])}`);
  return `{${entries.join(', ')}}`;
}

